insert into public.units (id, name, description, order_index, program, allotted_days, default_start_date) values
  ('proj-1', 'Term 1: Motion, Forces & Structures', 'Aug 31 – Dec 23 · nine academic weeks · from reading a graph to a bridge you designed yourself.', 1, 'projects', 67, '2026-08-31'),
  ('proj-2', 'Term 2: Energy', 'Jan 4 – Feb 12 · three academic weeks · where the energy goes.', 2, 'projects', 23, '2027-01-04'),
  ('proj-3', 'Term 3: Fluids, Waves & Electromagnetism', 'Mar 1 – Apr 16 · four academic weeks · pressure, sound, and the motor.', 3, 'projects', 36, '2027-03-01'),
  ('proj-4', 'Term 4: Generation & the Capstone', 'Apr 26 – Jun 10 · four academic weeks · the generator, then redesign one of your own builds and defend it.', 4, 'projects', 34, '2027-04-26')
insert into public.learning_targets (slug, statement, statement_es, domain, unit_id, content_strand, standard_refs, exclude_from_growth, order_index, program) values
  ('pp.w00.predict-lock', 'I can write a prediction and lock it before I test, and say what evidence would prove me wrong.', 'Puedo escribir una predicción y fijarla antes de probar, y decir qué evidencia demostraría que estoy equivocado.', 'reasoning', 'proj-1', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 1, 'projects'),
  ('pp.w00.timeline', 'I can keep an engineering timeline: what I planned, what actually happened, and why they differ.', 'Puedo llevar una línea de tiempo de ingeniería: lo que planeé, lo que pasó realmente y por qué son diferentes.', 'skill', 'proj-1', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 2, 'projects'),
  ('pp.w01.read-graph', 'I can read a position–time or velocity–time graph and say in words how the object moved.', 'Puedo leer una gráfica de posición–tiempo o velocidad–tiempo y decir con palabras cómo se movió el objeto.', 'knowledge', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 3, 'projects'),
  ('pp.w01.v-from-slope', 'I can find velocity from the slope of a position–time graph.', 'Puedo hallar la velocidad a partir de la pendiente de una gráfica posición–tiempo.', 'skill', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 4, 'projects'),
  ('pp.w01.a-from-slope', 'I can tell whether an object is speeding up, slowing down or steady from how the slope changes.', 'Puedo saber si un objeto acelera, frena o va constante por cómo cambia la pendiente.', 'reasoning', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 5, 'projects'),
  ('pp.w01.area', 'I can find displacement from the area under a velocity–time graph.', 'Puedo hallar el desplazamiento a partir del área bajo una gráfica velocidad–tiempo.', 'skill', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 6, 'projects'),
  ('pp.w01.sketch-first', 'I can sketch the graph of a motion before the screen shows it, and fix my sketch from the evidence.', 'Puedo dibujar la gráfica de un movimiento antes de que la pantalla la muestre, y corregir mi dibujo con la evidencia.', 'reasoning', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 7, 'projects'),
  ('pp.w02.a-vs-angle', 'I can measure a cart''s acceleration at several ramp angles and show how it changes.', 'Puedo medir la aceleración de un carrito en varios ángulos de rampa y mostrar cómo cambia.', 'skill', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 8, 'projects'),
  ('pp.w02.predict-fit', 'I can predict the run-out at a new angle from my own data before I release the cart.', 'Puedo predecir el recorrido en un ángulo nuevo a partir de mis propios datos antes de soltar el carrito.', 'reasoning', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 9, 'projects'),
  ('pp.w02.g-diluted', 'I can explain that the ramp dilutes gravity: steeper means closer to g.', 'Puedo explicar que la rampa diluye la gravedad: más inclinada significa más cerca de g.', 'knowledge', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 10, 'projects'),
  ('pp.w02.friction-gap', 'I can use friction to explain the gap between my prediction and the measurement.', 'Puedo usar la fricción para explicar la diferencia entre mi predicción y la medición.', 'reasoning', 'proj-1', 'motion-graphs', array['HS-PS2-1']::text[], false, 11, 'projects'),
  ('pp.w03.fbd', 'I can draw a free-body diagram of the car mid-run with every force labeled.', 'Puedo dibujar un diagrama de cuerpo libre del carro a mitad del recorrido con cada fuerza etiquetada.', 'skill', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 12, 'projects'),
  ('pp.w03.net-force', 'I can explain the car''s motion from the net force: speeding up while thrust wins, slowing when friction wins.', 'Puedo explicar el movimiento del carro a partir de la fuerza neta: acelera mientras gana el empuje, frena cuando gana la fricción.', 'reasoning', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 13, 'projects'),
  ('pp.w03.third-law', 'I can say what pushes on what when air leaves the balloon, and which is the thrust.', 'Puedo decir qué empuja a qué cuando el aire sale del globo, y cuál es el empuje.', 'knowledge', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 14, 'projects'),
  ('pp.w03.limit-claim', 'I can claim which force limits the run and back it with one controlled comparison.', 'Puedo afirmar qué fuerza limita el recorrido y respaldarlo con una comparación controlada.', 'reasoning', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 15, 'projects'),
  ('pp.w04.n3-momentum', 'I can explain the launch as momentum: water goes down, rocket goes up, and the totals match.', 'Puedo explicar el lanzamiento como cantidad de movimiento: el agua baja, el cohete sube y los totales coinciden.', 'knowledge', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 16, 'projects'),
  ('pp.w04.impulse', 'I can predict how changing water volume or pressure changes the impulse and the apex.', 'Puedo predecir cómo cambiar el volumen de agua o la presión cambia el impulso y la altura máxima.', 'reasoning', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 17, 'projects'),
  ('pp.w04.two-motions', 'I can treat the flight as two motions — up-and-down under gravity, and sideways — and say which one the wind touches.', 'Puedo tratar el vuelo como dos movimientos — arriba y abajo por la gravedad, y de lado — y decir cuál toca el viento.', 'reasoning', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 18, 'projects'),
  ('pp.w04.redesign-data', 'I can change one thing for launch two because of what launch one measured.', 'Puedo cambiar una cosa para el segundo lanzamiento por lo que midió el primero.', 'product', 'proj-1', 'forces-dynamics', array['HS-PS2-1', 'HS-PS2-2']::text[], false, 19, 'projects'),
  ('pp.w05.equilibrium', 'I can explain that a bridge that stays still has zero net force at every joint.', 'Puedo explicar que un puente que se queda quieto tiene fuerza neta cero en cada unión.', 'knowledge', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 20, 'projects'),
  ('pp.w05.tension-compression', 'I can label each member of a truss as tension or compression before it is loaded.', 'Puedo etiquetar cada miembro de una armadura como tensión o compresión antes de cargarla.', 'reasoning', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 21, 'projects'),
  ('pp.w05.triangles', 'I can explain why triangles hold their shape and rectangles do not.', 'Puedo explicar por qué los triángulos mantienen su forma y los rectángulos no.', 'knowledge', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 22, 'projects'),
  ('pp.w05.predict-member', 'I can predict which member fails first and check it against the load test.', 'Puedo predecir qué miembro falla primero y comprobarlo con la prueba de carga.', 'reasoning', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 23, 'projects'),
  ('pp.w06.constraints', 'I can write the constraints a design must meet before I sketch it.', 'Puedo escribir las restricciones que un diseño debe cumplir antes de dibujarlo.', 'skill', 'proj-1', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 24, 'projects'),
  ('pp.w06.torque', 'I can explain why a handle far from the mug''s center makes it harder to hold steady.', 'Puedo explicar por qué un asa lejos del centro de la taza hace más difícil sostenerla firme.', 'knowledge', 'proj-1', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 25, 'projects'),
  ('pp.w06.justify', 'I can choose one design from three and show that the choice follows from the constraints.', 'Puedo elegir un diseño entre tres y mostrar que la elección se deriva de las restricciones.', 'reasoning', 'proj-1', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 26, 'projects'),
  ('pp.w07.material-test', 'I can test single strands to find what one member can hold in tension and in compression.', 'Puedo probar hebras individuales para hallar lo que un miembro aguanta en tensión y en compresión.', 'skill', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 27, 'projects'),
  ('pp.w07.predict-load', 'I can predict my bridge''s failure load from the member I think goes first.', 'Puedo predecir la carga de fallo de mi puente a partir del miembro que creo que falla primero.', 'reasoning', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 28, 'projects'),
  ('pp.w07.design-constraint', 'I can design a bridge to a span, a mass limit and a load target, and say which constraint cost me the most.', 'Puedo diseñar un puente para una luz, un límite de masa y una carga objetivo, y decir qué restricción me costó más.', 'product', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 29, 'projects'),
  ('pp.w07.gap', 'I can explain the gap between predicted and actual failure load in terms of joints, buckling or a member I mislabeled.', 'Puedo explicar la diferencia entre la carga de fallo predicha y la real en términos de uniones, pandeo o un miembro mal etiquetado.', 'reasoning', 'proj-1', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 30, 'projects'),
  ('pp.w08.transfer', 'I can use what I learned from one build to explain a structure or motion I have never seen.', 'Puedo usar lo que aprendí de una construcción para explicar una estructura o un movimiento que nunca he visto.', 'reasoning', 'proj-1', 'transfer', array['HS-ETS1-3']::text[], false, 31, 'projects'),
  ('pp.w08.self-rate', 'I can rate myself honestly on every Term 1 target and point to the evidence.', 'Puedo evaluarme con honestidad en cada meta del trimestre 1 y señalar la evidencia.', 'skill', 'proj-1', 'transfer', array['HS-ETS1-3']::text[], false, 32, 'projects'),
  ('pp.w09.pe-ke', 'I can trace energy from height to speed along a track and say where it is at any point.', 'Puedo seguir la energía desde la altura hasta la rapidez a lo largo de una pista y decir dónde está en cualquier punto.', 'knowledge', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 33, 'projects'),
  ('pp.w09.loop-min', 'I can predict the minimum drop height for a loop of a given size before I build it.', 'Puedo predecir la altura mínima de caída para un rizo de un tamaño dado antes de construirlo.', 'reasoning', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 34, 'projects'),
  ('pp.w09.loss-fraction', 'I can report the energy lost to friction as a fraction of the starting energy.', 'Puedo informar la energía perdida por fricción como una fracción de la energía inicial.', 'skill', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 35, 'projects'),
  ('pp.w09.track-graph', 'I can read a track as an energy graph: height is potential, the rest is kinetic or lost.', 'Puedo leer una pista como una gráfica de energía: la altura es potencial, el resto es cinética o perdida.', 'reasoning', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 36, 'projects'),
  ('pp.w10.load-path', 'I can trace the load path from the top plate through the studs to the floor.', 'Puedo seguir la ruta de la carga desde la solera superior por los montantes hasta el piso.', 'knowledge', 'proj-2', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 37, 'projects'),
  ('pp.w10.racking', 'I can predict what a bare frame does when pushed sideways, and explain why sheathing stops it.', 'Puedo predecir lo que hace un bastidor sin forro cuando se empuja de lado, y explicar por qué el forro lo detiene.', 'reasoning', 'proj-2', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 38, 'projects'),
  ('pp.w10.sixteen', 'I can explain why studs are sixteen on center and measured to centers.', 'Puedo explicar por qué los montantes van a dieciséis pulgadas entre centros y se miden a los centros.', 'knowledge', 'proj-2', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 39, 'projects'),
  ('pp.w10.read-plan', 'I can build a wall section from a framing plan without asking what a symbol means.', 'Puedo construir una sección de pared a partir de un plano de bastidor sin preguntar qué significa un símbolo.', 'skill', 'proj-2', 'structures', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 40, 'projects'),
  ('pp.w11.elastic-pe', 'I can find the energy stored in a rubber band from its force–stretch curve.', 'Puedo hallar la energía almacenada en una banda elástica a partir de su curva fuerza–estiramiento.', 'skill', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 41, 'projects'),
  ('pp.w11.work-power', 'I can find the car''s kinetic energy at best speed and the power the band delivered.', 'Puedo hallar la energía cinética del carro a su mejor rapidez y la potencia que entregó la banda.', 'skill', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 42, 'projects'),
  ('pp.w11.efficiency', 'I can report efficiency as energy out over energy in, and say where the rest went.', 'Puedo informar la eficiencia como energía de salida sobre energía de entrada, y decir a dónde fue el resto.', 'reasoning', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 43, 'projects'),
  ('pp.w11.attack-loss', 'I can choose which loss to attack in the redesign and defend the choice with my numbers.', 'Puedo elegir qué pérdida atacar en el rediseño y defender la elección con mis números.', 'reasoning', 'proj-2', 'energy-transfer', array['HS-PS3-1', 'HS-PS3-3']::text[], false, 44, 'projects'),
  ('pp.w12.pressure', 'I can define pressure as force over area and use it with real syringe sizes.', 'Puedo definir la presión como fuerza sobre área y usarla con tamaños reales de jeringa.', 'knowledge', 'proj-3', 'fluids-pressure', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 45, 'projects'),
  ('pp.w12.pascal', 'I can explain that pressure is the same everywhere in the tube, so a small syringe can push a big one.', 'Puedo explicar que la presión es la misma en todo el tubo, así que una jeringa pequeña puede empujar una grande.', 'knowledge', 'proj-3', 'fluids-pressure', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 46, 'projects'),
  ('pp.w12.force-mult', 'I can predict the force multiplication from the two syringe diameters and measure it.', 'Puedo predecir la multiplicación de fuerza a partir de los dos diámetros de jeringa y medirla.', 'reasoning', 'proj-3', 'fluids-pressure', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 47, 'projects'),
  ('pp.w12.distance-cost', 'I can show that what you gain in force you pay in distance — work in equals work out.', 'Puedo mostrar que lo que ganas en fuerza lo pagas en distancia — el trabajo de entrada es igual al de salida.', 'reasoning', 'proj-3', 'fluids-pressure', array['HS-PS2-1', 'HS-ETS1-3']::text[], false, 48, 'projects'),
  ('pp.w13.wave-props', 'I can name amplitude, frequency and wavelength on a sound trace and say what each sounds like.', 'Puedo nombrar amplitud, frecuencia y longitud de onda en un registro de sonido y decir cómo suena cada una.', 'knowledge', 'proj-3', 'waves-sound', array['HS-PS4-1']::text[], false, 49, 'projects'),
  ('pp.w13.vibration', 'I can explain the chain from a groove wiggling a needle to air pressure at my ear.', 'Puedo explicar la cadena desde el surco que mueve la aguja hasta la presión del aire en mi oído.', 'reasoning', 'proj-3', 'waves-sound', array['HS-PS4-1']::text[], false, 50, 'projects'),
  ('pp.w13.amplitude-loud', 'I can predict how cone size changes loudness or pitch, then test it.', 'Puedo predecir cómo el tamaño del cono cambia el volumen o el tono, y luego probarlo.', 'reasoning', 'proj-3', 'waves-sound', array['HS-PS4-1']::text[], false, 51, 'projects'),
  ('pp.w13.resonance', 'I can explain why a cone or tube makes some frequencies louder than others.', 'Puedo explicar por qué un cono o tubo hace algunas frecuencias más fuertes que otras.', 'knowledge', 'proj-3', 'waves-sound', array['HS-PS4-1']::text[], false, 52, 'projects'),
  ('pp.w14.current-field', 'I can show that a current makes a magnetic field, with a compass.', 'Puedo mostrar que una corriente crea un campo magnético, con una brújula.', 'skill', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 53, 'projects'),
  ('pp.w14.force-current', 'I can explain that a current in a magnetic field feels a force, and which way.', 'Puedo explicar que una corriente en un campo magnético siente una fuerza, y en qué dirección.', 'knowledge', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 54, 'projects'),
  ('pp.w14.direction', 'I can predict the direction of rotation from the field and current, then reverse one and predict again.', 'Puedo predecir la dirección de giro a partir del campo y la corriente, luego invertir uno y predecir de nuevo.', 'reasoning', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 55, 'projects'),
  ('pp.w14.keeps-turning', 'I can explain why the motor keeps turning instead of stopping at one position.', 'Puedo explicar por qué el motor sigue girando en lugar de detenerse en una posición.', 'reasoning', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 56, 'projects'),
  ('pp.w15.coil-force', 'I can explain how a changing current in the coil makes a changing force on the magnet.', 'Puedo explicar cómo una corriente cambiante en la bobina produce una fuerza cambiante sobre el imán.', 'knowledge', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 57, 'projects'),
  ('pp.w15.cone-wave', 'I can explain how the cone''s motion becomes a pressure wave in the air.', 'Puedo explicar cómo el movimiento del cono se convierte en una onda de presión en el aire.', 'knowledge', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 58, 'projects'),
  ('pp.w15.chain', 'I can write the causal chain from signal to sound, one link per sentence, with no link missing.', 'Puedo escribir la cadena causal desde la señal hasta el sonido, un eslabón por oración, sin que falte ninguno.', 'reasoning', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 59, 'projects'),
  ('pp.w15.design-var', 'I can predict which change (more turns, stronger magnet, lighter cone) helps, then test it.', 'Puedo predecir qué cambio (más vueltas, imán más fuerte, cono más ligero) ayuda, y luego probarlo.', 'reasoning', 'proj-3', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 60, 'projects'),
  ('pp.w16.induction', 'I can explain that spinning a magnet past a coil makes a current — the motor run backwards.', 'Puedo explicar que girar un imán frente a una bobina produce una corriente — el motor al revés.', 'knowledge', 'proj-4', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 61, 'projects'),
  ('pp.w16.power-out', 'I can measure electrical power out with voltage and current.', 'Puedo medir la potencia eléctrica de salida con voltaje y corriente.', 'skill', 'proj-4', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 62, 'projects'),
  ('pp.w16.efficiency', 'I can estimate mechanical power in and report the turbine''s efficiency.', 'Puedo estimar la potencia mecánica de entrada e informar la eficiencia de la turbina.', 'reasoning', 'proj-4', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 63, 'projects'),
  ('pp.w16.blade-predict', 'I can predict which blade change raises efficiency and test it.', 'Puedo predecir qué cambio en las aspas aumenta la eficiencia y probarlo.', 'reasoning', 'proj-4', 'electromagnetism', array['HS-PS2-5', 'HS-PS3-3']::text[], false, 64, 'projects'),
  ('pp.w17.choose', 'I can choose an earlier build to redesign because of what its data and my gap explanation said.', 'Puedo elegir una construcción anterior para rediseñar por lo que dijeron sus datos y mi explicación de la diferencia.', 'reasoning', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 65, 'projects'),
  ('pp.w17.plan', 'I can write a redesign plan with a locked prediction of how much better it will do.', 'Puedo escribir un plan de rediseño con una predicción fijada de cuánto mejorará.', 'product', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 66, 'projects'),
  ('pp.w17.build', 'I can build the redesign and keep the timeline as I go.', 'Puedo construir el rediseño y llevar la línea de tiempo mientras avanzo.', 'skill', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 67, 'projects'),
  ('pp.w18.test', 'I can test the redesign against the original''s data under the same conditions.', 'Puedo probar el rediseño contra los datos del original en las mismas condiciones.', 'skill', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 68, 'projects'),
  ('pp.w18.defend', 'I can defend the redesign to a panel using my reasoning artifacts from both rounds.', 'Puedo defender el rediseño ante un panel usando mis artefactos de razonamiento de ambas rondas.', 'reasoning', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 69, 'projects'),
  ('pp.w18.honest', 'I can say plainly whether the redesign worked, and what the numbers say caused the result.', 'Puedo decir claramente si el rediseño funcionó, y qué dicen los números que causó el resultado.', 'reasoning', 'proj-4', 'engineering-design', array['HS-ETS1-2', 'HS-ETS1-3']::text[], false, 70, 'projects'),
  ('pp.w19.portfolio', 'I can assemble every reasoning artifact of the year and re-rate myself against the targets.', 'Puedo reunir todos los artefactos de razonamiento del año y reevaluarme frente a las metas.', 'skill', 'proj-4', 'metacognition', null, false, 71, 'projects'),
  ('pp.w19.growth', 'I can point to the artifact where my reasoning got better, and say what changed.', 'Puedo señalar el artefacto donde mi razonamiento mejoró, y decir qué cambió.', 'reasoning', 'proj-4', 'metacognition', null, false, 72, 'projects')
insert into public.mastery_tasks (slug, unit_id, prompt, rubric, program) values
  ('pp.t1.mastery-structure-you-have-not-seen', 'proj-1', 'You are handed a photo of a structure you have never seen — a real one, with a load on it — and a card-stock model of it. Label every member tension or compression, predict which fails first and at roughly what load from your own strand data, load the model, and explain the gap. Write it so a builder who was not here could follow it. / Te entregan la foto de una estructura que nunca has visto — una real, con carga — y un modelo de cartulina. Etiqueta cada miembro como tensión o compresión, predice cuál falla primero y aproximadamente a qué carga a partir de tus propios datos de hebras, carga el modelo y explica la diferencia. Escríbelo para que un constructor que no estuvo aquí pueda seguirlo.', '{"science": {"description": "Members labeled correctly; the load prediction uses the student''s own material data and the right member."}, "reasoning": {"description": "The prediction is locked before the test and the gap explanation follows from what actually failed, not from the answer."}, "communication": {"description": "A builder could follow it. Diagram first, then words — in either language."}, "transfer": {"description": "A structure never seen in class, argued from the same physics as the bridges."}}'::jsonb, 'projects'),
  ('pp.t2.mastery-where-the-energy-went', 'proj-2', 'You are given a machine you have not built — a spring launcher, a pendulum, a dropped mass on a lever — and the probes. Measure energy in, energy out, report the efficiency, and say where the rest went, with one change you would make and a prediction of what it would do. / Te dan una máquina que no has construido — un lanzador de resorte, un péndulo, una masa que cae sobre una palanca — y las sondas. Mide la energía de entrada y de salida, informa la eficiencia y di a dónde fue el resto, con un cambio que harías y una predicción de su efecto.', '{"science": {"description": "Energy in and out measured correctly with the probes; efficiency computed as a ratio."}, "reasoning": {"description": "The losses named are the ones the data supports; the proposed change attacks the biggest one."}, "communication": {"description": "Numbers in a table, the story in sentences, in either language."}, "transfer": {"description": "A machine not built in class, treated with the same energy accounting as the coaster and the air car."}}'::jsonb, 'projects'),
  ('pp.t3.mastery-chain-of-cause', 'proj-3', 'You are given a device that uses pressure, sound or electromagnetism — one you have not seen opened — and asked to open it, draw it, and write the chain of cause from input to output with no link missing. Then predict what one change would do and, if the device allows, test it. / Te dan un dispositivo que usa presión, sonido o electromagnetismo — uno que no has visto abierto — y te piden abrirlo, dibujarlo y escribir la cadena causal desde la entrada hasta la salida sin que falte ningún eslabón. Luego predice qué haría un cambio y, si el dispositivo lo permite, pruébalo.', '{"science": {"description": "Every link in the chain is physically correct — pressure, wave or field — and named with the right word."}, "reasoning": {"description": "No link is missing or magic; the predicted effect of the change follows from the chain."}, "communication": {"description": "The drawing carries the chain; the sentences carry the causes. Either language."}, "transfer": {"description": "A device not built in class, explained with the physics of the claw, the cone and the motor."}}'::jsonb, 'projects'),
  ('pp.t4.mastery-defend-a-redesign', 'proj-4', 'Defend your capstone redesign to a panel that has your first-round artifact in front of them. State the prediction you locked, the result, and whether it worked — plainly. Answer the panel''s questions from your numbers. / Defiende tu rediseño final ante un panel que tiene tu artefacto de la primera ronda enfrente. Indica la predicción que fijaste, el resultado y si funcionó — claramente. Responde las preguntas del panel con tus números.', '{"science": {"description": "The comparison was made under the same conditions and the measurements are sound."}, "reasoning": {"description": "The verdict follows from the numbers, including when the redesign lost."}, "communication": {"description": "The panel could follow it without reading the packet. Either language."}, "transfer": {"description": "Uses the year''s method — predict, build, measure, explain — on the student''s own earlier work."}}'::jsonb, 'projects')
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w00', 'Week 0 · Launch · Predict before you test / Lanzamiento · Predice antes de probar', 'Term 1: Motion, Forces & Structures', 'proj-1', 1, 'markdown', false, 110, 7, false, array['I can write a prediction and lock it before I test, and say what evidence would prove me wrong. / Puedo escribir una predicción y fijarla antes de probar, y decir qué evidencia demostraría que estoy equivocado.', 'I can keep an engineering timeline: what I planned, what actually happened, and why they differ. / Puedo llevar una línea de tiempo de ingeniería: lo que planeé, lo que pasó realmente y por qué son diferentes.']::text[], 'Academic week of 2026-08-31 · 4 days · Vernier motion detector', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can write a prediction and lock it before I test, and say what evidence would prove me wrong. / Puedo escribir una predicción y fijarla antes de probar, y decir qué evidencia demostraría que estoy equivocado."}, {"id": "t2", "type": "target", "statement": "I can keep an engineering timeline: what I planned, what actually happened, and why they differ. / Puedo llevar una línea de tiempo de ingeniería: lo que planeé, lo que pasó realmente y por qué son diferentes."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-08-31 · 4 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nSomething drops, rolls or flies in the first five minutes. Everyone writes a prediction on paper before anyone touches it. The prediction is graded for the reasoning, never for being right — say that out loud on day one.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | A demo with a locked prediction; norms for the four-segment block | Prediction frame: I think… because… / Creo que… porque… |\n| 2 | Vernier motion detector first touch — walk toward and away, watch the trace | Sketch what the screen showed and label it in either language |\n| 3 | Teams, roles, the packet, the timeline page | First timeline entry |\n| 4 | Mini-build: paper tower, 20 minutes, one locked prediction of height | Predicted vs. actual, one sentence on the gap |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nA locked prediction, the measured result, and one sentence explaining the gap.\n\n*Una predicción fijada, el resultado medido y una oración que explique la diferencia.*\n\n### Off-week question / Pregunta de la semana de taller\n\nFind one thing at your shop or at home that someone predicted before building. What did they predict, and were they right?\n\n*Encuentra algo en tu taller o en tu casa que alguien predijo antes de construir. ¿Qué predijo y tenía razón?*\n\n*Tools: Vernier motion detector*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w01', 'Week 1 · Describing motion · Foundation week / Describir el movimiento · Semana de base', 'Term 1: Motion, Forces & Structures', 'proj-1', 2, 'markdown', false, 110, 9, true, array['I can read a position–time or velocity–time graph and say in words how the object moved. / Puedo leer una gráfica de posición–tiempo o velocidad–tiempo y decir con palabras cómo se movió el objeto.', 'I can find velocity from the slope of a position–time graph. / Puedo hallar la velocidad a partir de la pendiente de una gráfica posición–tiempo.', 'I can tell whether an object is speeding up, slowing down or steady from how the slope changes. / Puedo saber si un objeto acelera, frena o va constante por cómo cambia la pendiente.', 'I can find displacement from the area under a velocity–time graph. / Puedo hallar el desplazamiento a partir del área bajo una gráfica velocidad–tiempo.', 'I can sketch the graph of a motion before the screen shows it, and fix my sketch from the evidence. / Puedo dibujar la gráfica de un movimiento antes de que la pantalla la muestre, y corregir mi dibujo con la evidencia.']::text[], 'Academic week of 2026-09-14 · 5 days · Vernier motion detector · sims: constant-velocity, uniformly-accelerated-motion, area-under-curve, slope-calculator', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can read a position–time or velocity–time graph and say in words how the object moved. / Puedo leer una gráfica de posición–tiempo o velocidad–tiempo y decir con palabras cómo se movió el objeto."}, {"id": "t2", "type": "target", "statement": "I can find velocity from the slope of a position–time graph. / Puedo hallar la velocidad a partir de la pendiente de una gráfica posición–tiempo."}, {"id": "t3", "type": "target", "statement": "I can tell whether an object is speeding up, slowing down or steady from how the slope changes. / Puedo saber si un objeto acelera, frena o va constante por cómo cambia la pendiente."}, {"id": "t4", "type": "target", "statement": "I can find displacement from the area under a velocity–time graph. / Puedo hallar el desplazamiento a partir del área bajo una gráfica velocidad–tiempo."}, {"id": "t5", "type": "target", "statement": "I can sketch the graph of a motion before the screen shows it, and fix my sketch from the evidence. / Puedo dibujar la gráfica de un movimiento antes de que la pantalla la muestre, y corregir mi dibujo con la evidencia."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-09-14 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nGraph matching with the motion detector: the screen never draws a graph a student has not already sketched. Walk the graph; then the reverse — sketch the graph of a walk before it appears.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Motion detector graph matching, both directions | Three sketches with the match score |\n| 2 | Sims: constant-velocity, uniformly-accelerated-motion — used only to CHECK a hand prediction | Predict / check / fix table |\n| 3 | Sims: area-under-curve, slope-calculator — a number out of a graph | One slope, one area, in their own words |\n| 4 | A real cart on the track with the motion detector | Sketch, then compare |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nA record of motion you have never seen: describe it and defend the description from the graph. Then draw the graph that WOULD match a motion described in words.\n\n*Un registro de movimiento que nunca has visto: descríbelo y defiende tu descripción con la gráfica. Luego dibuja la gráfica que correspondería a un movimiento descrito con palabras.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWatch one thing move at work or at home for ten seconds. Sketch its velocity–time graph from memory.\n\n*Observa algo moverse en el trabajo o en casa durante diez segundos. Dibuja de memoria su gráfica velocidad–tiempo.*\n\n*Tools: Vernier motion detector · sims: constant-velocity, uniformly-accelerated-motion, area-under-curve, slope-calculator*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w02', 'Week 2 · Car and ramp · Acceleration and its cause / Carro y rampa · La aceleración y su causa', 'Term 1: Motion, Forces & Structures', 'proj-1', 3, 'markdown', false, 110, 9, true, array['I can measure a cart''s acceleration at several ramp angles and show how it changes. / Puedo medir la aceleración de un carrito en varios ángulos de rampa y mostrar cómo cambia.', 'I can predict the run-out at a new angle from my own data before I release the cart. / Puedo predecir el recorrido en un ángulo nuevo a partir de mis propios datos antes de soltar el carrito.', 'I can explain that the ramp dilutes gravity: steeper means closer to g. / Puedo explicar que la rampa diluye la gravedad: más inclinada significa más cerca de g.', 'I can use friction to explain the gap between my prediction and the measurement. / Puedo usar la fricción para explicar la diferencia entre mi predicción y la medición.']::text[], 'Academic week of 2026-09-28 · 5 days · Vernier photogate + picket fence, or motion detector · sim: picket-fence-g', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can measure a cart''s acceleration at several ramp angles and show how it changes. / Puedo medir la aceleración de un carrito en varios ángulos de rampa y mostrar cómo cambia."}, {"id": "t2", "type": "target", "statement": "I can predict the run-out at a new angle from my own data before I release the cart. / Puedo predecir el recorrido en un ángulo nuevo a partir de mis propios datos antes de soltar el carrito."}, {"id": "t3", "type": "target", "statement": "I can explain that the ramp dilutes gravity: steeper means closer to g. / Puedo explicar que la rampa diluye la gravedad: más inclinada significa más cerca de g."}, {"id": "t4", "type": "target", "statement": "I can use friction to explain the gap between my prediction and the measurement. / Puedo usar la fricción para explicar la diferencia entre mi predicción y la medición."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-09-28 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nOne cart, one ramp, three angles. Which angle gives the biggest acceleration, and by how much? Prediction locked before the first run.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Cart on the ramp at 3 angles with photogate + picket fence (or motion detector) | a-vs-angle table and sketch |\n| 2 | Sim twin: picket-fence-g — what would the ramp read if it were vertical? | Extrapolate the fit toward 90° |\n| 3 | Run-out on the floor: measure distance after the ramp at two angles | Run-out vs. angle |\n| 4 | The test: predict run-out at a NEW angle, locked, then release | Predicted / actual / gap |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour prediction of run-out at the new angle, the measurement, and an explanation of the gap that names friction and says where it acted.\n\n*Tu predicción del recorrido en el ángulo nuevo, la medición y una explicación de la diferencia que nombre la fricción y diga dónde actuó.*\n\n### Off-week question / Pregunta de la semana de taller\n\nFind a ramp (a loading dock, a driveway, a wheelchair ramp). Estimate its angle. Would a cart reach g on it? Why not?\n\n*Encuentra una rampa (un muelle de carga, una entrada, una rampa de silla de ruedas). Estima su ángulo. ¿Alcanzaría un carrito la aceleración g en ella? ¿Por qué no?*\n\n*Tools: Vernier photogate + picket fence, or motion detector · sim: picket-fence-g*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w03', 'Week 3 · Balloon zip line · Newton''s laws / Tirolesa de globo · Las leyes de Newton', 'Term 1: Motion, Forces & Structures', 'proj-1', 4, 'markdown', false, 110, 7, true, array['I can draw a free-body diagram of the car mid-run with every force labeled. / Puedo dibujar un diagrama de cuerpo libre del carro a mitad del recorrido con cada fuerza etiquetada.', 'I can explain the car''s motion from the net force: speeding up while thrust wins, slowing when friction wins. / Puedo explicar el movimiento del carro a partir de la fuerza neta: acelera mientras gana el empuje, frena cuando gana la fricción.', 'I can say what pushes on what when air leaves the balloon, and which is the thrust. / Puedo decir qué empuja a qué cuando el aire sale del globo, y cuál es el empuje.', 'I can claim which force limits the run and back it with one controlled comparison. / Puedo afirmar qué fuerza limita el recorrido y respaldarlo con una comparación controlada.']::text[], 'Academic week of 2026-10-12 · 4 days · Balloons, straws, string, Duplo · sims: sumo-forces, carts-third-law, free-body-diagram', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can draw a free-body diagram of the car mid-run with every force labeled. / Puedo dibujar un diagrama de cuerpo libre del carro a mitad del recorrido con cada fuerza etiquetada."}, {"id": "t2", "type": "target", "statement": "I can explain the car''s motion from the net force: speeding up while thrust wins, slowing when friction wins. / Puedo explicar el movimiento del carro a partir de la fuerza neta: acelera mientras gana el empuje, frena cuando gana la fricción."}, {"id": "t3", "type": "target", "statement": "I can say what pushes on what when air leaves the balloon, and which is the thrust. / Puedo decir qué empuja a qué cuando el aire sale del globo, y cuál es el empuje."}, {"id": "t4", "type": "target", "statement": "I can claim which force limits the run and back it with one controlled comparison. / Puedo afirmar qué fuerza limita el recorrido y respaldarlo con una comparación controlada."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-10-12 · 4 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nSend a Duplo passenger across the room on a string. Who gets farthest — and what stopped the rest?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Build v1, first run, measure distance; FBD on the packet page | FBD with forces labeled in either language |\n| 2 | Controlled comparison: change ONE thing (passenger mass, balloon size, string type) | Claim + evidence |\n| 3 | Sim twin: sumo-forces / carts-third-law for the third-law pair | Third-law pairs table |\n| 4 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nA free-body diagram of the car mid-run and a claim about which force limits the run, backed by one comparison where only one thing changed.\n\n*Un diagrama de cuerpo libre del carro a mitad del recorrido y una afirmación sobre qué fuerza limita el recorrido, respaldada por una comparación donde solo cambió una cosa.*\n\n### Off-week question / Pregunta de la semana de taller\n\nName one thing at your shop that moves because something pushes back on it (a nail gun, a hose, a grinder). What is the pair of forces?\n\n*Nombra algo en tu taller que se mueve porque algo lo empuja de vuelta (una pistola de clavos, una manguera, una amoladora). ¿Cuál es el par de fuerzas?*\n\n*Tools: Balloons, straws, string, Duplo · sims: sumo-forces, carts-third-law, free-body-diagram*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w04', 'Week 4 · Water rockets · Impulse, momentum, projectiles / Cohetes de agua · Impulso, cantidad de movimiento, proyectiles', 'Term 1: Motion, Forces & Structures', 'proj-1', 5, 'markdown', false, 110, 9, true, array['I can explain the launch as momentum: water goes down, rocket goes up, and the totals match. / Puedo explicar el lanzamiento como cantidad de movimiento: el agua baja, el cohete sube y los totales coinciden.', 'I can predict how changing water volume or pressure changes the impulse and the apex. / Puedo predecir cómo cambiar el volumen de agua o la presión cambia el impulso y la altura máxima.', 'I can treat the flight as two motions — up-and-down under gravity, and sideways — and say which one the wind touches. / Puedo tratar el vuelo como dos movimientos — arriba y abajo por la gravedad, y de lado — y decir cuál toca el viento.', 'I can change one thing for launch two because of what launch one measured. / Puedo cambiar una cosa para el segundo lanzamiento por lo que midió el primero.']::text[], 'Academic week of 2026-10-26 · 5 days · Water rocket launcher, 2 L bottles, bike pump, stopwatch · sims: impulse-momentum, projectile-motion', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can explain the launch as momentum: water goes down, rocket goes up, and the totals match. / Puedo explicar el lanzamiento como cantidad de movimiento: el agua baja, el cohete sube y los totales coinciden."}, {"id": "t2", "type": "target", "statement": "I can predict how changing water volume or pressure changes the impulse and the apex. / Puedo predecir cómo cambiar el volumen de agua o la presión cambia el impulso y la altura máxima."}, {"id": "t3", "type": "target", "statement": "I can treat the flight as two motions — up-and-down under gravity, and sideways — and say which one the wind touches. / Puedo tratar el vuelo como dos movimientos — arriba y abajo por la gravedad, y de lado — y decir cuál toca el viento."}, {"id": "t4", "type": "target", "statement": "I can change one thing for launch two because of what launch one measured. / Puedo cambiar una cosa para el segundo lanzamiento por lo que midió el primero."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-10-26 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nOutdoors, last dependable week for it. Two liters, a launcher, a stopwatch. How high, and what decides it?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Build: fins, nose, a water line marked; prediction of apex from water volume | Locked prediction with an impulse reason |\n| 2 | Launch 1, timed flight, apex from hang time; sim twin: impulse-momentum | Measured apex vs. prediction |\n| 3 | Sim: projectile-motion — tilt the launcher, predict range | Two-motion sketch |\n| 4 | Launch 2 = the redesign, one change, locked prediction | Predicted / actual / gap |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour prediction of apex from the water and pressure you chose, the measured apex, the gap explained, and the ONE change you made for launch two and why.\n\n*Tu predicción de la altura máxima a partir del agua y la presión que elegiste, la altura medida, la explicación de la diferencia y el ÚNICO cambio que hiciste para el segundo lanzamiento y por qué.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWhat in your trade uses pressure to move something? How is it like the rocket, and how is it not?\n\n*¿Qué en tu oficio usa presión para mover algo? ¿En qué se parece al cohete y en qué no?*\n\n*Tools: Water rocket launcher, 2 L bottles, bike pump, stopwatch · sims: impulse-momentum, projectile-motion*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w05', 'Week 5 · Card-stock bridges from a template · Equilibrium / Puentes de cartulina con plantilla · Equilibrio', 'Term 1: Motion, Forces & Structures', 'proj-1', 6, 'markdown', false, 110, 7, true, array['I can explain that a bridge that stays still has zero net force at every joint. / Puedo explicar que un puente que se queda quieto tiene fuerza neta cero en cada unión.', 'I can label each member of a truss as tension or compression before it is loaded. / Puedo etiquetar cada miembro de una armadura como tensión o compresión antes de cargarla.', 'I can explain why triangles hold their shape and rectangles do not. / Puedo explicar por qué los triángulos mantienen su forma y los rectángulos no.', 'I can predict which member fails first and check it against the load test. / Puedo predecir qué miembro falla primero y comprobarlo con la prueba de carga.']::text[], 'Academic week of 2026-11-09 · 4 days · Card stock, glue, bridge template, load bucket + sand · sim: free-body-diagram', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can explain that a bridge that stays still has zero net force at every joint. / Puedo explicar que un puente que se queda quieto tiene fuerza neta cero en cada unión."}, {"id": "t2", "type": "target", "statement": "I can label each member of a truss as tension or compression before it is loaded. / Puedo etiquetar cada miembro de una armadura como tensión o compresión antes de cargarla."}, {"id": "t3", "type": "target", "statement": "I can explain why triangles hold their shape and rectangles do not. / Puedo explicar por qué los triángulos mantienen su forma y los rectángulos no."}, {"id": "t4", "type": "target", "statement": "I can predict which member fails first and check it against the load test. / Puedo predecir qué miembro falla primero y comprobarlo con la prueba de carga."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-11-09 · 4 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nTemplated on purpose — a four-day week and a first structure should not also be an open design. Cut, fold, glue; then decide which member goes first.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Cut and assemble from the template; push and pull on a bare rectangle vs. a triangle | Which shape held, and why |\n| 2 | Label every member T or C before loading; sim twin: free-body-diagram at one joint | Labeled truss diagram |\n| 3 | Load test to failure; watch which member went | Predicted / actual failure member |\n| 4 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour labeled truss (tension / compression), your predicted first failure, what actually failed, and what that tells you about your labels.\n\n*Tu armadura etiquetada (tensión / compresión), tu predicción del primer fallo, lo que falló realmente y lo que eso te dice sobre tus etiquetas.*\n\n### Off-week question / Pregunta de la semana de taller\n\nFind a triangle holding something up at your shop or on the way home. Which side is being pulled and which is being pushed?\n\n*Encuentra un triángulo que sostenga algo en tu taller o de camino a casa. ¿Qué lado está siendo jalado y cuál empujado?*\n\n*Tools: Card stock, glue, bridge template, load bucket + sand · sim: free-body-diagram*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w06', 'Week 6 · Coffee mug redesign · The design process / Rediseño de una taza · El proceso de diseño', 'Term 1: Motion, Forces & Structures', 'proj-1', 7, 'markdown', false, 110, 5, false, array['I can write the constraints a design must meet before I sketch it. / Puedo escribir las restricciones que un diseño debe cumplir antes de dibujarlo.', 'I can explain why a handle far from the mug''s center makes it harder to hold steady. / Puedo explicar por qué un asa lejos del centro de la taza hace más difícil sostenerla firme.', 'I can choose one design from three and show that the choice follows from the constraints. / Puedo elegir un diseño entre tres y mostrar que la elección se deriva de las restricciones.']::text[], 'Academic week of 2026-11-23 · 3 days · Mugs, a scale, sketch paper', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can write the constraints a design must meet before I sketch it. / Puedo escribir las restricciones que un diseño debe cumplir antes de dibujarlo."}, {"id": "t2", "type": "target", "statement": "I can explain why a handle far from the mug''s center makes it harder to hold steady. / Puedo explicar por qué un asa lejos del centro de la taza hace más difícil sostenerla firme."}, {"id": "t3", "type": "target", "statement": "I can choose one design from three and show that the choice follows from the constraints. / Puedo elegir un diseño entre tres y mostrar que la elección se deriva de las restricciones."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-11-23 · 3 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nThree days before Thanksgiving is the wrong time for a load test and the right time for a design sprint. Interview a user, write constraints, sketch three, choose one.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Interview a partner about their mug; write constraints | Constraint list |\n| 2 | Three sketches; center-of-mass and handle torque with a real mug on a scale | Sketches with one physics note each |\n| 3 | Choose one, justify; reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour constraints, your three sketches, and a justification page showing that the design you chose actually follows from the constraints you wrote.\n\n*Tus restricciones, tus tres bocetos y una página de justificación que muestre que el diseño que elegiste realmente se deriva de las restricciones que escribiste.*\n\n### Off-week question / Pregunta de la semana de taller\n\nPick one tool you use every week. What is one constraint its designer clearly had, and one they clearly ignored?\n\n*Elige una herramienta que uses cada semana. ¿Cuál es una restricción que su diseñador claramente tuvo y una que claramente ignoró?*\n\n*Tools: Mugs, a scale, sketch paper*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w07', 'Week 7 · Pasta bridges · Open structural design / Puentes de pasta · Diseño estructural abierto', 'Term 1: Motion, Forces & Structures', 'proj-1', 8, 'markdown', false, 110, 9, true, array['I can test single strands to find what one member can hold in tension and in compression. / Puedo probar hebras individuales para hallar lo que un miembro aguanta en tensión y en compresión.', 'I can predict my bridge''s failure load from the member I think goes first. / Puedo predecir la carga de fallo de mi puente a partir del miembro que creo que falla primero.', 'I can design a bridge to a span, a mass limit and a load target, and say which constraint cost me the most. / Puedo diseñar un puente para una luz, un límite de masa y una carga objetivo, y decir qué restricción me costó más.', 'I can explain the gap between predicted and actual failure load in terms of joints, buckling or a member I mislabeled. / Puedo explicar la diferencia entre la carga de fallo predicha y la real en términos de uniones, pandeo o un miembro mal etiquetado.']::text[], 'Academic week of 2026-12-07 · 5 days · Spaghetti, hot glue, load bucket + sand, Vernier force sensor for strand tests', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can test single strands to find what one member can hold in tension and in compression. / Puedo probar hebras individuales para hallar lo que un miembro aguanta en tensión y en compresión."}, {"id": "t2", "type": "target", "statement": "I can predict my bridge''s failure load from the member I think goes first. / Puedo predecir la carga de fallo de mi puente a partir del miembro que creo que falla primero."}, {"id": "t3", "type": "target", "statement": "I can design a bridge to a span, a mass limit and a load target, and say which constraint cost me the most. / Puedo diseñar un puente para una luz, un límite de masa y una carga objetivo, y decir qué restricción me costó más."}, {"id": "t4", "type": "target", "statement": "I can explain the gap between predicted and actual failure load in terms of joints, buckling or a member I mislabeled. / Puedo explicar la diferencia entre la carga de fallo predicha y la real en términos de uniones, pandeo o un miembro mal etiquetado."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-12-07 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nThe template is gone. Span, mass limit, load target. Before you build, test one strand — how much does one piece of pasta actually hold?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Strand tests: tension and compression to failure; constraints on the packet page | Material test table |\n| 2 | Design on paper, labeled T/C, predicted failure load from the weakest member | Locked prediction |\n| 3 | Build | Timeline entry: planned vs. actual build time |\n| 4 | Load test to failure | Predicted / actual / what went first |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nMember-by-member: which goes first and why; your predicted failure load from your own strand tests; the actual; and an explanation of the gap.\n\n*Miembro por miembro: cuál falla primero y por qué; tu carga de fallo predicha a partir de tus propias pruebas de hebras; la real; y una explicación de la diferencia.*\n\n### Off-week question / Pregunta de la semana de taller\n\nLook at a real bridge or a roof truss. Find the member you would worry about most. Why that one?\n\n*Mira un puente real o una armadura de techo. Encuentra el miembro que más te preocuparía. ¿Por qué ese?*\n\n*Tools: Spaghetti, hot glue, load bucket + sand, Vernier force sensor for strand tests*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w08', 'Week 8 · Term 1 checkpoint · Re-activation / Punto de control del trimestre 1 · Reactivación', 'Term 1: Motion, Forces & Structures', 'proj-1', 9, 'markdown', false, 110, 5, false, array['I can use what I learned from one build to explain a structure or motion I have never seen. / Puedo usar lo que aprendí de una construcción para explicar una estructura o un movimiento que nunca he visto.', 'I can rate myself honestly on every Term 1 target and point to the evidence. / Puedo evaluarme con honestidad en cada meta del trimestre 1 y señalar la evidencia.']::text[], 'Academic week of 2026-12-21 · 3 days · Packet, Term 1 artifacts', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can use what I learned from one build to explain a structure or motion I have never seen. / Puedo usar lo que aprendí de una construcción para explicar una estructura o un movimiento que nunca he visto."}, {"id": "t2", "type": "target", "statement": "I can rate myself honestly on every Term 1 target and point to the evidence. / Puedo evaluarme con honestidad en cada meta del trimestre 1 y señalar la evidencia."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2026-12-21 · 3 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nNot a new build. A transfer task on something they have not seen, a self-rating against every Term 1 target, and the first real read of the engineering timeline.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Transfer task: a new structure or motion, argued from the graph or the FBD | The transfer task |\n| 2 | Self-rating on every Term 1 target with the artifact that proves it | Rating sheet |\n| 3 | Timeline read: where did planned and actual diverge most this term, and why? | Timeline reflection |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThe transfer task, and your self-rating with the artifact you point to for each target.\n\n*La tarea de transferencia y tu autoevaluación con el artefacto que señalas para cada meta.*\n\n### Off-week question / Pregunta de la semana de taller\n\nVacation. Nothing is due. Bring back one photo of a structure that interests you.\n\n*Vacaciones. No hay nada que entregar. Trae una foto de una estructura que te interese.*\n\n*Tools: Packet, Term 1 artifacts*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w09', 'Week 9 · Marble roller coasters · Energy conservation / Montañas rusas de canica · Conservación de la energía', 'Term 2: Energy', 'proj-2', 10, 'markdown', false, 110, 9, true, array['I can trace energy from height to speed along a track and say where it is at any point. / Puedo seguir la energía desde la altura hasta la rapidez a lo largo de una pista y decir dónde está en cualquier punto.', 'I can predict the minimum drop height for a loop of a given size before I build it. / Puedo predecir la altura mínima de caída para un rizo de un tamaño dado antes de construirlo.', 'I can report the energy lost to friction as a fraction of the starting energy. / Puedo informar la energía perdida por fricción como una fracción de la energía inicial.', 'I can read a track as an energy graph: height is potential, the rest is kinetic or lost. / Puedo leer una pista como una gráfica de energía: la altura es potencial, el resto es cinética o perdida.']::text[], 'Academic week of 2027-01-04 · 5 days · Roller-coaster card-stock templates, marbles, Vernier photogate', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can trace energy from height to speed along a track and say where it is at any point. / Puedo seguir la energía desde la altura hasta la rapidez a lo largo de una pista y decir dónde está en cualquier punto."}, {"id": "t2", "type": "target", "statement": "I can predict the minimum drop height for a loop of a given size before I build it. / Puedo predecir la altura mínima de caída para un rizo de un tamaño dado antes de construirlo."}, {"id": "t3", "type": "target", "statement": "I can report the energy lost to friction as a fraction of the starting energy. / Puedo informar la energía perdida por fricción como una fracción de la energía inicial."}, {"id": "t4", "type": "target", "statement": "I can read a track as an energy graph: height is potential, the rest is kinetic or lost. / Puedo leer una pista como una gráfica de energía: la altura es potencial, el resto es cinética o perdida."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-01-04 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nCard-stock track from templates. Before the loop goes in: how high does the start have to be for the marble to make it round? Locked, then built.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Build the straight run; measure marble speed at the bottom with a photogate; compare to the height | Height vs. speed table |\n| 2 | Predict the minimum drop for the loop; lock it | Locked prediction with an energy reason |\n| 3 | Build the loop; find the real minimum by lowering the start | Predicted / actual |\n| 4 | Loss as a fraction of starting energy; where does it go? | Loss fraction and where |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour predicted minimum drop for the loop, the measured one, and the difference expressed as the fraction of starting energy that friction took.\n\n*Tu altura mínima de caída predicha para el rizo, la medida, y la diferencia expresada como la fracción de la energía inicial que se llevó la fricción.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWhere in your trade does something go up so that it can come down with energy? (A pile driver, a hammer, a load on a hoist.)\n\n*¿Dónde en tu oficio algo sube para que pueda bajar con energía? (Un martinete, un martillo, una carga en un montacargas.)*\n\n*Tools: Roller-coaster card-stock templates, marbles, Vernier photogate*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w10', 'Week 10 · Balsa stick-framed wall · Structures from a plan / Pared de bastidor de balsa · Estructuras a partir de un plano', 'Term 2: Energy', 'proj-2', 11, 'markdown', false, 110, 5, false, array['I can trace the load path from the top plate through the studs to the floor. / Puedo seguir la ruta de la carga desde la solera superior por los montantes hasta el piso.', 'I can predict what a bare frame does when pushed sideways, and explain why sheathing stops it. / Puedo predecir lo que hace un bastidor sin forro cuando se empuja de lado, y explicar por qué el forro lo detiene.', 'I can explain why studs are sixteen on center and measured to centers. / Puedo explicar por qué los montantes van a dieciséis pulgadas entre centros y se miden a los centros.', 'I can build a wall section from a framing plan without asking what a symbol means. / Puedo construir una sección de pared a partir de un plano de bastidor sin preguntar qué significa un símbolo.']::text[], 'Academic week of 2027-01-18 · 3 days · Balsa, glue, framing plan, card stock for sheathing', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can trace the load path from the top plate through the studs to the floor. / Puedo seguir la ruta de la carga desde la solera superior por los montantes hasta el piso."}, {"id": "t2", "type": "target", "statement": "I can predict what a bare frame does when pushed sideways, and explain why sheathing stops it. / Puedo predecir lo que hace un bastidor sin forro cuando se empuja de lado, y explicar por qué el forro lo detiene."}, {"id": "t3", "type": "target", "statement": "I can explain why studs are sixteen on center and measured to centers. / Puedo explicar por qué los montantes van a dieciséis pulgadas entre centros y se miden a los centros."}, {"id": "t4", "type": "target", "statement": "I can build a wall section from a framing plan without asking what a symbol means. / Puedo construir una sección de pared a partir de un plano de bastidor sin preguntar qué significa un símbolo."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-01-18 · 3 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nThree days, a templated build, and the direct link to the trades section. Frame it; then push it sideways before and after sheathing.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Frame from the plan: plates, studs at 16 o.c., a header | Load-path sketch |\n| 2 | Rack the bare frame (predict first); sheathe one side; rack again | Predicted / actual racking |\n| 3 | Why triangulation was hiding in a rectangle; reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour prediction of what the bare frame does when racked, what it did, and why the sheathing changed it — with the hidden triangle drawn.\n\n*Tu predicción de lo que hace el bastidor sin forro al empujarlo de lado, lo que hizo, y por qué el forro lo cambió — con el triángulo escondido dibujado.*\n\n### Off-week question / Pregunta de la semana de taller\n\nLook at a wall being framed or a stud wall opened up. Where is the shear resistance actually coming from?\n\n*Mira una pared que se esté armando o una pared de montantes abierta. ¿De dónde viene realmente la resistencia al corte?*\n\n*Tools: Balsa, glue, framing plan, card stock for sheathing*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w11', 'Week 11 · Lou-Vee air cars · Work, power, efficiency / Carros de aire Lou-Vee · Trabajo, potencia, eficiencia', 'Term 2: Energy', 'proj-2', 12, 'markdown', false, 110, 9, true, array['I can find the energy stored in a rubber band from its force–stretch curve. / Puedo hallar la energía almacenada en una banda elástica a partir de su curva fuerza–estiramiento.', 'I can find the car''s kinetic energy at best speed and the power the band delivered. / Puedo hallar la energía cinética del carro a su mejor rapidez y la potencia que entregó la banda.', 'I can report efficiency as energy out over energy in, and say where the rest went. / Puedo informar la eficiencia como energía de salida sobre energía de entrada, y decir a dónde fue el resto.', 'I can choose which loss to attack in the redesign and defend the choice with my numbers. / Puedo elegir qué pérdida atacar en el rediseño y defender la elección con mis números.']::text[], 'Academic week of 2027-02-01 · 5 days · Lou-Vee air car kits, Vernier force sensor, motion detector or photogate', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can find the energy stored in a rubber band from its force–stretch curve. / Puedo hallar la energía almacenada en una banda elástica a partir de su curva fuerza–estiramiento."}, {"id": "t2", "type": "target", "statement": "I can find the car''s kinetic energy at best speed and the power the band delivered. / Puedo hallar la energía cinética del carro a su mejor rapidez y la potencia que entregó la banda."}, {"id": "t3", "type": "target", "statement": "I can report efficiency as energy out over energy in, and say where the rest went. / Puedo informar la eficiencia como energía de salida sobre energía de entrada, y decir a dónde fue el resto."}, {"id": "t4", "type": "target", "statement": "I can choose which loss to attack in the redesign and defend the choice with my numbers. / Puedo elegir qué pérdida atacar en el rediseño y defender la elección con mis números."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-02-01 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nRubber-band propeller cars. The band stores energy; the car gets some of it. How much, and where did the rest go?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Build v1; force–stretch curve of the band with the force sensor | Curve and area = stored energy |\n| 2 | Run: speed with the motion detector or photogate; kinetic energy | Energy in / energy out |\n| 3 | Efficiency; list the losses (prop, axle, air); pick ONE to attack | Loss list with a choice |\n| 4 | Redesign run, locked prediction of the new efficiency | Predicted / actual |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nEnergy stored in the band (from your curve), kinetic energy at best speed, the efficiency, where the rest went, and the one loss you attacked and what it did.\n\n*Energía almacenada en la banda (de tu curva), energía cinética a la mejor rapidez, la eficiencia, a dónde fue el resto, y la pérdida que atacaste y qué efecto tuvo.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWinter vacation follows. Nothing is due. Find one machine at work with an efficiency rating on its plate. What is it?\n\n*Siguen las vacaciones de invierno. No hay nada que entregar. Encuentra una máquina en el trabajo con una eficiencia en su placa. ¿Cuál es?*\n\n*Tools: Lou-Vee air car kits, Vernier force sensor, motion detector or photogate*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w12', 'Week 12 · Hydraulic claws · Pressure and Pascal / Garras hidráulicas · Presión y Pascal', 'Term 3: Fluids, Waves & Electromagnetism', 'proj-3', 13, 'markdown', false, 110, 9, true, array['I can define pressure as force over area and use it with real syringe sizes. / Puedo definir la presión como fuerza sobre área y usarla con tamaños reales de jeringa.', 'I can explain that pressure is the same everywhere in the tube, so a small syringe can push a big one. / Puedo explicar que la presión es la misma en todo el tubo, así que una jeringa pequeña puede empujar una grande.', 'I can predict the force multiplication from the two syringe diameters and measure it. / Puedo predecir la multiplicación de fuerza a partir de los dos diámetros de jeringa y medirla.', 'I can show that what you gain in force you pay in distance — work in equals work out. / Puedo mostrar que lo que ganas en fuerza lo pagas en distancia — el trabajo de entrada es igual al de salida.']::text[], 'Academic week of 2027-03-01 · 5 days · Syringes (two sizes), tubing, craft sticks, two Vernier force sensors', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can define pressure as force over area and use it with real syringe sizes. / Puedo definir la presión como fuerza sobre área y usarla con tamaños reales de jeringa."}, {"id": "t2", "type": "target", "statement": "I can explain that pressure is the same everywhere in the tube, so a small syringe can push a big one. / Puedo explicar que la presión es la misma en todo el tubo, así que una jeringa pequeña puede empujar una grande."}, {"id": "t3", "type": "target", "statement": "I can predict the force multiplication from the two syringe diameters and measure it. / Puedo predecir la multiplicación de fuerza a partir de los dos diámetros de jeringa y medirla."}, {"id": "t4", "type": "target", "statement": "I can show that what you gain in force you pay in distance — work in equals work out. / Puedo mostrar que lo que ganas en fuerza lo pagas en distancia — el trabajo de entrada es igual al de salida."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-03-01 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nSyringes and tubing. Push the small one; the big one moves — with more force and less distance. Predict the ratio from the diameters before you measure it.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Measure syringe diameters; predict force ratio; lock it | Locked prediction |\n| 2 | Measure force in vs. out with two force sensors; distances too | Force and distance table |\n| 3 | Build the claw (3–4 syringes) | Timeline entry |\n| 4 | Claw challenge: lift a known mass; work in vs. work out | Work in / work out |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour predicted force multiplication from the diameters, the measured one, and the reconciliation with distance — work in vs. work out.\n\n*Tu multiplicación de fuerza predicha a partir de los diámetros, la medida, y la reconciliación con la distancia — trabajo de entrada vs. trabajo de salida.*\n\n### Off-week question / Pregunta de la semana de taller\n\nFind a hydraulic system at work (a jack, a lift, a brake). Which cylinder is small and which is big, and why that way round?\n\n*Encuentra un sistema hidráulico en el trabajo (un gato, un elevador, un freno). ¿Qué cilindro es pequeño y cuál es grande, y por qué en ese orden?*\n\n*Tools: Syringes (two sizes), tubing, craft sticks, two Vernier force sensors*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w13', 'Week 13 · Record player and megaphone · Sound as a wave / Tocadiscos y megáfono · El sonido como onda', 'Term 3: Fluids, Waves & Electromagnetism', 'proj-3', 14, 'markdown', false, 110, 9, true, array['I can name amplitude, frequency and wavelength on a sound trace and say what each sounds like. / Puedo nombrar amplitud, frecuencia y longitud de onda en un registro de sonido y decir cómo suena cada una.', 'I can explain the chain from a groove wiggling a needle to air pressure at my ear. / Puedo explicar la cadena desde el surco que mueve la aguja hasta la presión del aire en mi oído.', 'I can predict how cone size changes loudness or pitch, then test it. / Puedo predecir cómo el tamaño del cono cambia el volumen o el tono, y luego probarlo.', 'I can explain why a cone or tube makes some frequencies louder than others. / Puedo explicar por qué un cono o tubo hace algunas frecuencias más fuertes que otras.']::text[], 'Academic week of 2027-03-15 · 5 days · Records, paper cones, pins, Vernier microphone, tone generator', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can name amplitude, frequency and wavelength on a sound trace and say what each sounds like. / Puedo nombrar amplitud, frecuencia y longitud de onda en un registro de sonido y decir cómo suena cada una."}, {"id": "t2", "type": "target", "statement": "I can explain the chain from a groove wiggling a needle to air pressure at my ear. / Puedo explicar la cadena desde el surco que mueve la aguja hasta la presión del aire en mi oído."}, {"id": "t3", "type": "target", "statement": "I can predict how cone size changes loudness or pitch, then test it. / Puedo predecir cómo el tamaño del cono cambia el volumen o el tono, y luego probarlo."}, {"id": "t4", "type": "target", "statement": "I can explain why a cone or tube makes some frequencies louder than others. / Puedo explicar por qué un cono o tubo hace algunas frecuencias más fuertes que otras."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-03-15 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nA paper cone, a pin, a record spun by hand. Music comes out. Then a megaphone. What is the cone doing to the groove''s motion, and to the air?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Paper-cone record player; Vernier microphone shows the trace | Sketch the trace; label amplitude and frequency |\n| 2 | Cone size vs. loudness — predict, lock, measure with the microphone | Predicted / actual |\n| 3 | Build the megaphone; resonance with a tuning fork or tone generator | Which frequency got louder |\n| 4 | Chain of cause: groove → needle → cone → air → ear, one link per sentence | Chain page |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThe chain from groove to ear, one link per sentence, and your tested prediction about cone size — with the microphone traces that decided it.\n\n*La cadena desde el surco hasta el oído, un eslabón por oración, y tu predicción probada sobre el tamaño del cono — con los registros del micrófono que la decidieron.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWhere at your shop is it loud, and what shape is the space? Would a different shape change it?\n\n*¿Dónde en tu taller hay mucho ruido, y qué forma tiene el espacio? ¿Cambiaría con otra forma?*\n\n*Tools: Records, paper cones, pins, Vernier microphone, tone generator*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w14', 'Week 14 · World''s simplest motor · Current, field, force / El motor más simple del mundo · Corriente, campo, fuerza', 'Term 3: Fluids, Waves & Electromagnetism', 'proj-3', 15, 'markdown', false, 110, 9, true, array['I can show that a current makes a magnetic field, with a compass. / Puedo mostrar que una corriente crea un campo magnético, con una brújula.', 'I can explain that a current in a magnetic field feels a force, and which way. / Puedo explicar que una corriente en un campo magnético siente una fuerza, y en qué dirección.', 'I can predict the direction of rotation from the field and current, then reverse one and predict again. / Puedo predecir la dirección de giro a partir del campo y la corriente, luego invertir uno y predecir de nuevo.', 'I can explain why the motor keeps turning instead of stopping at one position. / Puedo explicar por qué el motor sigue girando en lugar de detenerse en una posición.']::text[], 'Academic week of 2027-03-29 · 5 days · AA batteries, neodymium magnets, copper wire, compasses', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can show that a current makes a magnetic field, with a compass. / Puedo mostrar que una corriente crea un campo magnético, con una brújula."}, {"id": "t2", "type": "target", "statement": "I can explain that a current in a magnetic field feels a force, and which way. / Puedo explicar que una corriente en un campo magnético siente una fuerza, y en qué dirección."}, {"id": "t3", "type": "target", "statement": "I can predict the direction of rotation from the field and current, then reverse one and predict again. / Puedo predecir la dirección de giro a partir del campo y la corriente, luego invertir uno y predecir de nuevo."}, {"id": "t4", "type": "target", "statement": "I can explain why the motor keeps turning instead of stopping at one position. / Puedo explicar por qué el motor sigue girando en lugar de detenerse en una posición."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-03-29 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nBattery, magnet, a bent wire. It spins. Before the first spin: which way? Then flip the magnet — which way now?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Compass next to a current-carrying wire; field direction | Compass sketches |\n| 2 | Build the motor; predict rotation direction, locked; spin | Predicted / actual direction |\n| 3 | Reverse the magnet, then the battery; predict each first | Two more predictions |\n| 4 | Why it keeps turning; a homopolar motor variant | Explanation page |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThree predictions of rotation direction (original, magnet flipped, battery flipped), each made before the spin, and an explanation of why it keeps turning.\n\n*Tres predicciones de la dirección de giro (original, imán invertido, batería invertida), cada una hecha antes de girar, y una explicación de por qué sigue girando.*\n\n### Off-week question / Pregunta de la semana de taller\n\nFind a motor at work. Where is the magnet, and where does the current go in?\n\n*Encuentra un motor en el trabajo. ¿Dónde está el imán y por dónde entra la corriente?*\n\n*Tools: AA batteries, neodymium magnets, copper wire, compasses*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w15', 'Week 15 · Build a speaker · Electromagnetism drives sound / Construye un altavoz · El electromagnetismo produce sonido', 'Term 3: Fluids, Waves & Electromagnetism', 'proj-3', 16, 'markdown', false, 110, 9, true, array['I can explain how a changing current in the coil makes a changing force on the magnet. / Puedo explicar cómo una corriente cambiante en la bobina produce una fuerza cambiante sobre el imán.', 'I can explain how the cone''s motion becomes a pressure wave in the air. / Puedo explicar cómo el movimiento del cono se convierte en una onda de presión en el aire.', 'I can write the causal chain from signal to sound, one link per sentence, with no link missing. / Puedo escribir la cadena causal desde la señal hasta el sonido, un eslabón por oración, sin que falte ninguno.', 'I can predict which change (more turns, stronger magnet, lighter cone) helps, then test it. / Puedo predecir qué cambio (más vueltas, imán más fuerte, cono más ligero) ayuda, y luego probarlo.']::text[], 'Academic week of 2027-04-12 · 5 days · Magnet wire, neodymium magnets, paper cups, 3.5 mm cable, Vernier microphone', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can explain how a changing current in the coil makes a changing force on the magnet. / Puedo explicar cómo una corriente cambiante en la bobina produce una fuerza cambiante sobre el imán."}, {"id": "t2", "type": "target", "statement": "I can explain how the cone''s motion becomes a pressure wave in the air. / Puedo explicar cómo el movimiento del cono se convierte en una onda de presión en el aire."}, {"id": "t3", "type": "target", "statement": "I can write the causal chain from signal to sound, one link per sentence, with no link missing. / Puedo escribir la cadena causal desde la señal hasta el sonido, un eslabón por oración, sin que falte ninguno."}, {"id": "t4", "type": "target", "statement": "I can predict which change (more turns, stronger magnet, lighter cone) helps, then test it. / Puedo predecir qué cambio (más vueltas, imán más fuerte, cono más ligero) ayuda, y luego probarlo."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-04-12 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nCoil, magnet, cup. Plug it into a phone. Sound. This is the motor and the record player in one object — say how.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Wind the coil, mount on the cup, magnet behind; first sound | Sketch with parts labeled |\n| 2 | Chain of cause from signal to sound | Chain page |\n| 3 | Predict which ONE change helps loudness; lock; measure with the microphone | Predicted / actual |\n| 4 | Second variable if time; compare to the motor and the record player | Comparison table |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThe causal chain from signal to sound with no link missing, and your tested prediction about the one design change you made.\n\n*La cadena causal desde la señal hasta el sonido sin que falte ningún eslabón, y tu predicción probada sobre el único cambio de diseño que hiciste.*\n\n### Off-week question / Pregunta de la semana de taller\n\nLook at a speaker grille at work or in a car. Estimate the cone size. What would a bigger one do better and worse?\n\n*Mira la rejilla de un altavoz en el trabajo o en un carro. Estima el tamaño del cono. ¿Qué haría mejor y peor uno más grande?*\n\n*Tools: Magnet wire, neodymium magnets, paper cups, 3.5 mm cable, Vernier microphone*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w16', 'Week 16 · Wind and water turbines · Induction and power / Turbinas de viento y agua · Inducción y potencia', 'Term 4: Generation & the Capstone', 'proj-4', 17, 'markdown', false, 110, 9, true, array['I can explain that spinning a magnet past a coil makes a current — the motor run backwards. / Puedo explicar que girar un imán frente a una bobina produce una corriente — el motor al revés.', 'I can measure electrical power out with voltage and current. / Puedo medir la potencia eléctrica de salida con voltaje y corriente.', 'I can estimate mechanical power in and report the turbine''s efficiency. / Puedo estimar la potencia mecánica de entrada e informar la eficiencia de la turbina.', 'I can predict which blade change raises efficiency and test it. / Puedo predecir qué cambio en las aspas aumenta la eficiencia y probarlo.']::text[], 'Academic week of 2027-04-26 · 5 days · Small DC motors, blade kits, fan, Vernier voltage + current probes', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can explain that spinning a magnet past a coil makes a current — the motor run backwards. / Puedo explicar que girar un imán frente a una bobina produce una corriente — el motor al revés."}, {"id": "t2", "type": "target", "statement": "I can measure electrical power out with voltage and current. / Puedo medir la potencia eléctrica de salida con voltaje y corriente."}, {"id": "t3", "type": "target", "statement": "I can estimate mechanical power in and report the turbine''s efficiency. / Puedo estimar la potencia mecánica de entrada e informar la eficiencia de la turbina."}, {"id": "t4", "type": "target", "statement": "I can predict which blade change raises efficiency and test it. / Puedo predecir qué cambio en las aspas aumenta la eficiencia y probarlo."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-04-26 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nA DC motor with blades on it, a fan or a tap. The motor becomes a generator. How much comes out, compared with what went in?\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Motor as generator: spin by hand, read voltage; blades v1 on the fan | Voltage vs. spin |\n| 2 | Power out with Vernier voltage + current probes and a load resistor | P = V·I table |\n| 3 | Mechanical power in (fan speed / water flow estimate); efficiency | Efficiency |\n| 4 | Predict ONE blade change; lock; test | Predicted / actual |\n| 5 | Reasoning artifact + rate yourself | The artifact |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nPower out vs. your estimate of power in, the efficiency, and your tested prediction about the one blade change.\n\n*Potencia de salida frente a tu estimación de potencia de entrada, la eficiencia y tu predicción probada sobre el único cambio de aspas.*\n\n### Off-week question / Pregunta de la semana de taller\n\nWhere does the electricity at your shop come from? Follow it back one step. What is spinning?\n\n*¿De dónde viene la electricidad de tu taller? Síguela un paso hacia atrás. ¿Qué está girando?*\n\n*Tools: Small DC motors, blade kits, fan, Vernier voltage + current probes*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w17', 'Week 17 · Capstone I · Redesign one of your own builds / Proyecto final I · Rediseña una de tus construcciones', 'Term 4: Generation & the Capstone', 'proj-4', 18, 'markdown', false, 110, 9, true, array['I can choose an earlier build to redesign because of what its data and my gap explanation said. / Puedo elegir una construcción anterior para rediseñar por lo que dijeron sus datos y mi explicación de la diferencia.', 'I can write a redesign plan with a locked prediction of how much better it will do. / Puedo escribir un plan de rediseño con una predicción fijada de cuánto mejorará.', 'I can build the redesign and keep the timeline as I go. / Puedo construir el rediseño y llevar la línea de tiempo mientras avanzo.']::text[], 'Academic week of 2027-05-10 · 5 days · Whatever the chosen build needs', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can choose an earlier build to redesign because of what its data and my gap explanation said. / Puedo elegir una construcción anterior para rediseñar por lo que dijeron sus datos y mi explicación de la diferencia."}, {"id": "t2", "type": "target", "statement": "I can write a redesign plan with a locked prediction of how much better it will do. / Puedo escribir un plan de rediseño con una predicción fijada de cuánto mejorará."}, {"id": "t3", "type": "target", "statement": "I can build the redesign and keep the timeline as I go. / Puedo construir el rediseño y llevar la línea de tiempo mientras avanzo."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-05-10 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nTwo-week arc, with a shop week in the middle. This week: choose, plan, predict, build. The shop week carries only a question. Next academic week: test and defend.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Read your own timeline and gap explanations; choose the build | Choice with the reason |\n| 2 | Redesign plan; locked prediction of improvement | Locked prediction |\n| 3 | Build | Timeline |\n| 4 | Build; dry run | Timeline |\n| 5 | Build complete; what will you measure and how? Rate yourself | Test plan |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nYour redesign plan: the build you chose and why (from its data), the one change, and a locked prediction of how much better it will do.\n\n*Tu plan de rediseño: la construcción que elegiste y por qué (a partir de sus datos), el único cambio y una predicción fijada de cuánto mejorará.*\n\n### Off-week question / Pregunta de la semana de taller\n\nShop week. Nothing is due. One question: if the redesign does NOT beat the original, what will you say caused it?\n\n*Semana de taller. No hay nada que entregar. Una pregunta: si el rediseño NO supera al original, ¿qué dirás que lo causó?*\n\n*Tools: Whatever the chosen build needs*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w18', 'Week 18 · Capstone II · Test and defend / Proyecto final II · Prueba y defiende', 'Term 4: Generation & the Capstone', 'proj-4', 19, 'markdown', false, 110, 9, true, array['I can test the redesign against the original''s data under the same conditions. / Puedo probar el rediseño contra los datos del original en las mismas condiciones.', 'I can defend the redesign to a panel using my reasoning artifacts from both rounds. / Puedo defender el rediseño ante un panel usando mis artefactos de razonamiento de ambas rondas.', 'I can say plainly whether the redesign worked, and what the numbers say caused the result. / Puedo decir claramente si el rediseño funcionó, y qué dicen los números que causó el resultado.']::text[], 'Academic week of 2027-05-24 · 5 days · The redesigned build, the original data', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can test the redesign against the original''s data under the same conditions. / Puedo probar el rediseño contra los datos del original en las mismas condiciones."}, {"id": "t2", "type": "target", "statement": "I can defend the redesign to a panel using my reasoning artifacts from both rounds. / Puedo defender el rediseño ante un panel usando mis artefactos de razonamiento de ambas rondas."}, {"id": "t3", "type": "target", "statement": "I can say plainly whether the redesign worked, and what the numbers say caused the result. / Puedo decir claramente si el rediseño funcionó, y qué dicen los números que causó el resultado."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-05-24 · 5 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nSame conditions as the original. Test. Then stand up and defend it — in either language — to a panel that has your first-round artifact in front of them.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Test under the original conditions; compare to the original data | Original / redesign / gap |\n| 2 | Prepare the defense: three slides or one page, both artifacts | Defense page |\n| 3 | Defenses, half the room | Panel notes |\n| 4 | Defenses, other half | Panel notes |\n| 5 | Rate yourself on the capstone targets | Rating |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThe comparison of original and redesign under the same conditions, and your defense — with the honest sentence about whether it worked.\n\n*La comparación del original y el rediseño en las mismas condiciones, y tu defensa — con la oración honesta sobre si funcionó.*\n\n### Off-week question / Pregunta de la semana de taller\n\nShop week. Bring back every artifact from the year for the portfolio.\n\n*Semana de taller. Trae todos los artefactos del año para el portafolio.*\n\n*Tools: The redesigned build, the original data*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
insert into public.lessons (slug, title, unit, unit_id, lesson_number, lesson_type, published, estimated_time, planned_days, transfer_core, objectives, description, content_blocks, content) values ('pp-w19', 'Week 19 · Portfolio and final self-assessment / Portafolio y autoevaluación final', 'Term 4: Generation & the Capstone', 'proj-4', 20, 'markdown', false, 110, 7, false, array['I can assemble every reasoning artifact of the year and re-rate myself against the targets. / Puedo reunir todos los artefactos de razonamiento del año y reevaluarme frente a las metas.', 'I can point to the artifact where my reasoning got better, and say what changed. / Puedo señalar el artefacto donde mi razonamiento mejoró, y decir qué cambió.']::text[], 'Academic week of 2027-06-07 · 4 days · Packet, every artifact', '{"schemaVersion": 1, "dayType": "ANCHOR", "blocks": [{"id": "t1", "type": "target", "statement": "I can assemble every reasoning artifact of the year and re-rate myself against the targets. / Puedo reunir todos los artefactos de razonamiento del año y reevaluarme frente a las metas."}, {"id": "t2", "type": "target", "statement": "I can point to the artifact where my reasoning got better, and say what changed. / Puedo señalar el artefacto donde mi razonamiento mejoró, y decir qué cambió."}, {"id": "c1", "type": "callout", "variant": "note", "title": "Academic week of 2027-06-07 · 4 days · B and C", "markdown": "**Predict. Build. Measure. Explain.** Your packet page is on paper, Spanish and English side by side — do the work there. This page is the plan and the targets. / Tu página del paquete está en papel, español e inglés lado a lado — haz el trabajo ahí."}, {"id": "p1", "type": "prose", "markdown": "### This week / Esta semana\n\nEvery artifact of the year, the timeline as the cover page. Re-rate. Find the one where it changed.\n\n| Day | Hands (first) | On the packet page |\n|---|---|---|\n| 1 | Assemble and order the artifacts; timeline cover page | Cover page |\n| 2 | Re-rate every target with the evidence | Rating sheet |\n| 3 | The growth page: where did it change? | Growth page |\n| 4 | Hand it over | — |\n\n**Every block, four segments:** hands → record → talk (pairs, either language) → write (the packet frame). Hands always first.\n\n### Reasoning artifact / Artefacto de razonamiento\n\nThe portfolio, with the timeline as cover and the growth page inside.\n\n*El portafolio, con la línea de tiempo como portada y la página de crecimiento adentro.*\n\n### Off-week question / Pregunta de la semana de taller\n\nSummer.\n\n*Verano.*\n\n*Tools: Packet, every artifact*"}]}'::jsonb, '') on conflict (slug) do update set title = excluded.title, unit = excluded.unit, unit_id = excluded.unit_id, lesson_number = excluded.lesson_number, estimated_time = excluded.estimated_time, planned_days = excluded.planned_days, transfer_core = excluded.transfer_core, objectives = excluded.objectives, description = excluded.description, content_blocks = excluded.content_blocks, updated_at = now();
